-- Two integration-workflow posts: Creator AI + Opus Clip, and Creator AI + vidIQ.
--
-- Continues the creator-ai-plus-* series (CapCut, Canva, ChatGPT) with the two
-- gaps that series left: repurposing long form into Shorts, and the keyword
-- research handoff. Both tools are ones YouTubers already pay for, and both
-- sides of each handoff are things Creator AI does not do, so neither post has
-- to argue anyone out of a subscription to be useful.
--
-- STEP 0 checked against every published focus keyword and every keywords[]
-- entry first. Neither "opus clip shorts workflow" nor "vidiq youtube seo
-- workflow" is owned by an existing post, and both differ from their nearest
-- neighbours on intent and audience: best-ai-tools-to-turn-long-videos-into-
-- shorts-2026 is read by someone choosing a clipper, creator-ai-vs-vidiq and
-- best-vidiq-alternatives by someone deciding whether to keep paying. These two
-- are read by someone who already uses the tool and wants the handoff. Each
-- cross-links to its nearest neighbour so the distinction stays legible.
--
-- Every external claim is sourced in the post body: Opus Clip's pricing page and
-- its Virality Score help doc, vidIQ's plans page and its features-and-credits
-- help article, and YouTube's own search, Shorts and captions documentation.
-- Product numbers are checkable in this repo: 60s Starter dub cap
-- (STARTER_MAX_DUB_SECONDS), 5 thumbnails per run (thumbnail.schema.ts), 29
-- dubbing targets (supportedLanguages, 30 entries including English source).
--
-- Cadence: the newest live post is 2026-09-01. Opus Clip lands 2026-09-05 (4d)
-- and vidIQ 2026-09-09 (4d). The second date is in the future on purpose:
-- lib/blog-source.ts filters every read path on published_at <= now(), so it
-- schedules rather than dumping two posts into one week.
--
-- Same shape as 20260901000000_seed_competitor_comparison_posts.sql: one
-- dollar-quoted JSON blob unpacked by jsonb_to_recordset, idempotent via
-- ON CONFLICT (slug) DO UPDATE. branded_cta is included here rather than
-- backfilled, since the column exists as of 20260903000000.

INSERT INTO public.blog_posts (
  slug, title, excerpt, content, category, author_name, read_time,
  featured, tags, keywords, faqs, videos, branded_cta,
  seo_title, seo_description, focus_keyword, status, published_at
)
SELECT
  s.slug, s.title, s.excerpt, s.content, s.category, s.author_name, s.read_time,
  s.featured, s.tags, s.keywords, s.faqs, s.videos, s.branded_cta,
  s.seo_title, s.seo_description, s.focus_keyword, 'published', s.published_at
FROM jsonb_to_recordset($blogseed$[{"slug":"creator-ai-plus-opus-clip-shorts-workflow-for-youtube-2026","title":"Creator AI + Opus Clip: The Shorts Workflow That Stops Burning Credits","excerpt":"Opus Clip bills by the minute of source footage, not by the clip. So the cheapest way to get better Shorts is to write a long form video that already contains them.","content":"> **What is the best Opus Clip shorts workflow?** Write the long form video so it already contains standalone segments, then let Opus Clip find them. Opus Clip meters processing by the minute of source footage rather than by the clip, so a rambling ninety minute recording costs four times what a tight twenty minute one does and returns worse clips. The Opus Clip shorts workflow below moves the expensive decisions upstream into the script, where they cost nothing.\n\n![The opus clip shorts workflow starts in the story builder, not in the clipper](/story%20page.png)\n\nAlmost every guide to clipping tools is a review of the clipper. That is the wrong end of the problem. The clipper is a search function, and a search function is limited by what is in the thing it searches.\n\nThis is the practical version: what to change before the upload, what to pay for, and where the handoff genuinely fails.\n\n## Why the Opus Clip shorts workflow starts before you press record\n\nOpus Clip ranks its output with a Virality Score. Its [own documentation](https://help.opus.pro/docs/article/virality-score) says the score runs from 0 to 99 and that the AI weighs four things: Hook, Flow, Value and Trend. It is available on the Starter and Pro plans, not on Free.\n\nRead that list again as a creator rather than as a buyer. Hook and Flow are not properties of a clipping tool. They are properties of the recording. A hook exists because somebody wrote one. Flow exists because the segment resolves without depending on the fourteen minutes before it.\n\nSo the ceiling on your clips is set before the file is uploaded. The clipper can only find the best forty seconds that exist. If the best forty seconds in your video are a mid sentence tangent, that is what you get back, scored 71, with captions on it.\n\nThat is the single idea this **opus clip shorts workflow** is built around.\n\n## What Opus Clip actually charges you for\n\nOpus Clip's [pricing page](https://www.opus.pro/pricing) lists Free at $0, Starter at $15 a month, Pro at $29 a month, and a custom Business tier. Free renders up to 1080p, keeps clips for three days, and watermarks the animated caption templates. Starter and Pro export without a watermark.\n\nThe part that changes how you work is the meter. Processing is billed against the length of the source video you upload, not the number of clips it returns. Ten clips from a sixty minute podcast and two clips from the same file cost the same. Confirm the current allowance on the pricing page before you commit, because these numbers move.\n\nThat single fact reverses the intuition most people bring to a clipping tool. You are not paying for output. You are paying for input. Feeding it everything is the expensive habit.\n\n| Job | Opus Clip | Creator AI |\n|---|---|---|\n| Finding clip candidates in existing footage | Yes, this is the product | No |\n| Reframing horizontal to vertical with tracking | Yes | No |\n| Burned in animated captions on the clip | Yes | No |\n| Scoring a clip for likely engagement | Yes, Virality Score | No |\n| Writing the long form so clips exist | No | Yes, script and story builder |\n| Structuring for retention before filming | No | Yes, with a retention score |\n| Subtitle file for the long form upload | No | Yes, SRT you can correct |\n| Dubbing the finished video or clip | No | Yes, 29 languages |\n\nNeither column is a replacement for the other. The overlap is genuinely zero, which is rare enough to be worth saying plainly.\n\n## The seven step Opus Clip shorts workflow\n\n### Step 1: Design the long form to have seams\n\nOpen the story builder and outline the video as three or four segments that each survive on their own. Each one gets a micro hook in its first sentence and finishes its own thought. The retention score tells you where the outline sags before you have filmed anything.\n\nThis is the whole trick. A video built as one continuous argument has no clean cut points, and no clipper invents them.\n\n### Step 2: Write the script with the seams intact\n\nGenerate the script through your trained voice profile with timestamps on. Resist the transition sentences that make a video flow beautifully and make a clip incomprehensible. \"As I said earlier\" is a phrase that costs you a Short.\n\n### Step 3: Record and publish the long form first\n\nThe long form upload is the asset. YouTube's [search and discovery documentation](https://support.google.com/youtube/answer/141805) says videos are ranked on \"How well the title, description, and video content match the viewer's search\", plus engagement. The Shorts are distribution for something that already exists, not a replacement for it.\n\nCaption the long form properly while you are here. Generate the subtitles, fix the names and jargon in the editor, and upload a corrected SRT rather than trusting automatic captions.\n\n### Step 4: Upload only the minutes worth clipping\n\nHere is where the meter changes your behaviour. Do not hand Opus Clip a ninety minute stream and hope. Trim to the sections your outline already flagged as self contained, then upload that.\n\nOn a sixty minute recording where twenty minutes are genuinely clippable, this is a two thirds saving on every pass, every month, forever. It is also the step almost nobody does, because uploading the whole file feels like getting more for the money.\n\n### Step 5: Sort by Virality Score, then overrule it\n\nOpus Clip sorts results by score. Treat that as a first pass filter, not a verdict. The score cannot know that clip four gives away the answer your long form video is built to withhold, or that clip seven is a client's name pronounced wrong.\n\nWatch the top eight, keep three, delete the rest. Keeping everything is how a channel ends up with forty Shorts and no identity.\n\n### Step 6: Give every Short its own title and description\n\nA Short is a video, and YouTube treats it like one. Google's [Shorts documentation](https://support.google.com/youtube/answer/10059070) confirms Shorts run up to 3 minutes and surface in search results, on the home feed, on your channel page and in subscription feeds, not only in the Shorts tab.\n\nSo the clip that inherits \"Podcast Ep 42 Clip 3\" as a title is throwing away the one field the ranking system reads directly. Write the title for the search the clip answers. Put the link to the long form video in the description.\n\nSkip the tag box. The same YouTube page says tags are \"Not important\" and exist mainly to catch spelling mistakes.\n\n### Step 7: Dub the three that worked\n\nThis is the step that makes the arithmetic pleasant. The free plan caps a dub at 60 seconds of source, which is a real constraint on a twelve minute video and almost none at all on a Short.\n\nTake the clip that outperformed, dub it into a second language, and upload it as its own Short on the same channel. You are testing an audience for the cost of one clip rather than one full video. Which languages are worth the effort is answered with numbers in the [dubbing ROI breakdown](/blog/is-youtube-dubbing-worth-it-roi-breakdown-2026).\n\n## The credit math nobody does before subscribing\n\nTake a creator publishing one 45 minute podcast a week.\n\nUploading the full episode every week is 180 minutes of source a month. Uploading only the 15 minutes the outline marked as clippable is 60 minutes of source a month. Same number of usable Shorts, because the discarded 30 minutes per episode were never going to produce one.\n\nThat is a plan tier of difference, bought by spending twenty minutes on an outline you should have written anyway. Every clipping tool prices this way, which is why this part of the **opus clip shorts workflow** transfers even if you switch tools later.\n\n## Where Opus Clip is better left alone\n\nDo not over apply the handoff. Several things here have no equivalent upstream:\n\n- **ReframeAnything**, which keeps a moving subject centred when converting horizontal to vertical. Doing this by hand is miserable.\n- **Burned in animated captions**, which are correct for a feed where nobody enables a caption track.\n- **ClipAnything**, which searches footage by a plain language prompt, useful for gameplay and interviews where the interesting moment is visual rather than spoken.\n- **Publishing to several platforms in one pass**, which is a real time saving and not a feature worth rebuilding.\n\n## Where this Opus Clip shorts workflow breaks\n\n**Interviews and podcasts you do not control.** If a guest rambles, no amount of upstream planning saves you. Steps 4 through 7 still apply, step 1 does not.\n\n**Captions burned into a rendered clip.** Once a clip is rendered, a wrong name is fixed by re editing and re rendering, not by editing text. Say the difficult words clearly on the day, or accept the re render.\n\n**Clips that need a hook the recording never had.** A clipper cannot write. If every candidate opens weakly, the problem is upstream and the credits you spend looking are wasted twice.\n\n**Volume as a strategy.** Shorts viewers convert to long form subscribers slowly. Three good clips a week beats twenty, and the **opus clip shorts workflow** is designed to produce three.\n\n## The short version\n\nOpus Clip is a very good search function pointed at your footage. Search functions do not create the thing they find.\n\nWrite the long form so it contains three self contained segments, upload only those minutes, keep three clips, title each one for a real search, and dub the winner. That is the entire **opus clip shorts workflow**, and the expensive half of it happens in a text editor before anything is filmed. [Start free](/signup) and build the outline first.\n\n## Keep Reading\n\n- [The Best AI Tools to Turn Long Videos Into Shorts](/blog/best-ai-tools-to-turn-long-videos-into-shorts-2026)\n- [YouTube Shorts Script Generator: Hooks That Stop the Scroll](/blog/youtube-shorts-script-generator-hooks-that-stop-the-scroll-2026)\n- [YouTube Video Story Structure for Retention](/blog/youtube-video-story-structure-for-retention-2026)\n- [Creator AI + CapCut: From AI Script to Subtitled, Dubbed Video](/blog/creator-ai-plus-capcut-youtube-workflow-2026)\n- Outline it, film it, clip it. [Start free](/signup) or [see plans](/pricing).","category":"Workflows","author_name":"Afrin Nahar","read_time":"9 min read","featured":false,"tags":["Workflow","Opus Clip","Shorts","Repurposing"],"keywords":["how to use opus clip with an ai script writer","opus clip credits explained 2026","repurpose long form video into shorts workflow","opus clip virality score meaning","shorts from podcast without wasting credits"],"faqs":[{"question":"How does Opus Clip charge for processing?","answer":"By the length of the source video you upload rather than by the number of clips it returns. Ten clips and two clips from the same sixty minute file cost the same. That is why trimming to the sections worth clipping before you upload is the single highest leverage step in the workflow."},{"question":"What is the Virality Score and should I trust it?","answer":"It is Opus Clip's 0 to 99 rating of how likely a clip is to perform, weighing Hook, Flow, Value and Trend, and it is available on the Starter and Pro plans rather than Free. Treat it as a first pass filter. It cannot know that a clip gives away the answer your long form video was built to hold back."},{"question":"Do I need a script to use a clipping tool?","answer":"No, but the clips get better when you have one. A clipper searches for the best standalone segment that exists in the footage. If the video was written as one continuous argument with no self contained sections, there is nothing good to find, and you pay for the search either way."},{"question":"Can I fix a wrong name in Opus Clip's burned in captions?","answer":"Not after rendering, without re editing and re rendering the clip. Burned in captions are pixels. This is the one place the workflow is genuinely unforgiving, so say difficult names and product terms clearly on the day rather than planning to fix them later."},{"question":"Should each Short get its own title and description?","answer":"Yes. YouTube ranks on how well the title, description and video content match a search, and Shorts appear in search results as well as the Shorts feed. A clip inheriting a title like 'Episode 42 Clip 3' throws away the field the ranking system reads most directly."},{"question":"Is dubbing a Short worth it?","answer":"It is the cheapest language test available. A Short is under three minutes, so a dub costs very little compared to a full video, and the free plan's sixty second cap is barely a constraint at that length. Dub the one clip that already outperformed rather than the whole back catalogue."}],"videos":[],"branded_cta":{"title":"Structure your next video for retention","description":"The story builder turns a topic into a beat-by-beat outline with a retention score, so you can see where viewers would drop off before you film it.","buttonLabel":"Build my story outline","buttonHref":"/signup"},"seo_title":"Opus Clip Shorts Workflow 2026: Stop Wasting Credits","seo_description":"An Opus Clip shorts workflow that starts in the script, not the clipper: write clippable long form, spend credits once, publish Shorts that rank.","focus_keyword":"opus clip shorts workflow","published_at":"2026-09-05T12:00:00.000Z"},{"slug":"creator-ai-plus-vidiq-youtube-seo-workflow-2026","title":"Creator AI + vidIQ: The YouTube SEO Workflow That Skips the Tag Theatre","excerpt":"vidIQ finds the demand. YouTube says tags are not important. Here is the six step handoff that turns a researched keyword into a script, a title and a video the search page actually wants.","content":"> **What is the best vidIQ YouTube SEO workflow?** Use vidIQ for the half it is genuinely good at, finding demand and reading competitors, then stop at the tag box. YouTube's own documentation ranks videos on \"How well the title, description, and video content match the viewer's search\", and says tags are \"Not important\". A vidIQ YouTube SEO workflow that spends an hour on tags and ten minutes on the script has the ratio exactly backwards.\n\n![The vidiq youtube seo workflow turns a researched keyword into a full script](/scripts%20page.png)\n\nvidIQ is the most installed YouTube research tool there is, and most of the advice about it is written by people selling a competitor. This is neither. It is the handoff we actually recommend to creators who already pay for it.\n\n## What YouTube says ranks a video\n\nStart here, because the rest of the workflow follows from it. YouTube's [search and discovery page](https://support.google.com/youtube/answer/141805) states that videos are ranked on \"How well the title, description, and video content match the viewer's search\", and on which videos drive the most engagement for that search.\n\nThe same page addresses tags directly. They are \"Not important\", and exist mainly to correct common spelling mistakes.\n\nThree inputs, then. Title. Description. The video itself. Everything in this **vidiq youtube seo workflow** is arranged around those three and nothing else.\n\nNotice which of the three is the largest. \"Video content\" is not a metadata field you fill in at upload. It is the script, the structure, and whether the thing you promised in the title is actually in the video. That is the part no research tool touches.\n\n## Where vidIQ genuinely earns its place\n\nFour things, and they are all upstream of the camera:\n\n**Keyword research with volume and competition.** The core reason to open it. Knowing that a topic has demand before you spend three days on it is real information, even as an estimate.\n\n**Competitor reading through the extension.** Views per hour overlaid on other people's videos while you browse YouTube normally. This is passive rather than a chore, which is why it is the feature people actually keep using.\n\n**Daily Ideas.** Suggestions generated against your channel's own history rather than a generic trending list.\n\n**AI Coach.** A chat interface that will audit a channel and answer strategy questions, useful mostly as a second opinion on decisions you have already half made.\n\nNone of that is a script, a structure, or a video. It is a brief.\n\n## The credit math, honestly\n\nThis is the part that decides how you use the tool, and it is documented in vidIQ's own [features and credits help article](https://support.vidiq.com/en/articles/13928456-features-credits-by-plan).\n\nvidIQ gives every plan a shared monthly pool of AI credits: 150 on Free, 1,000 on Pro, 2,000 to 3,000 on Boost, and 6,000 to 10,000 on Max, varying by how many channels you connect. Credits are shared across every AI tool, so spending them in one place removes them from another. The article is explicit that unused credits do not roll over.\n\nThe individual prices matter more than the totals. AI Coach costs 10 credits a message for normal use. A thumbnail generation costs 22 credits. Script writing costs 1 credit per minute of script.\n\nRun that against the free tier. 150 credits is fifteen coach messages, or six thumbnails, or one 10 minute script plus a bit of change. It is a demonstration, not a workflow. Current plan pricing is on [vidIQ's plans page](https://vidiq.com/plans/), and it changes often enough that any table including this one goes stale.\n\nThe practical reading: spend vidIQ credits on the thing only vidIQ can do, which is research against live channel data. Spending them on script minutes is buying the cheapest commodity in the stack with the most constrained currency you own.\n\n## The six step vidIQ YouTube SEO workflow\n\n### Step 1: Find the demand, and only the demand\n\nIn vidIQ, research the topic. Take three things out: the phrase people actually search, the competition estimate, and the two or three related phrases worth covering inside the video.\n\nTake nothing else. Not the tag suggestions, not the SEO score, not the recommended description template.\n\n### Step 2: Check the result page yourself\n\nSearch the phrase on YouTube, signed out. If the first five results are five years old and have 40,000 views, that is an opportunity. If they are from channels a hundred times your size and posted last week, it is a wall.\n\nEstimated volume tells you nobody is asking. It does not tell you whether the answer is already given better. Two minutes here saves the three days that step 1 is trying to protect.\n\n### Step 3: Hand the keyword to the script, not to the tag box\n\nThis is the actual handoff and the reason this **vidiq youtube seo workflow** exists.\n\nPaste the phrase and the related terms into Creator AI as the topic. The script is generated through a voice profile trained on videos you have already published, so the terms land in sentences you would plausibly say rather than in a paragraph that reads like it was written for a crawler.\n\nEnable timestamps. The result is both a shooting plan and, later, the spine of your description.\n\n### Step 4: Structure it so the promise is kept\n\nRun the topic through the story builder before writing the final draft. You get a beat by beat outline with hooks, escalation points and a retention score.\n\nThis step exists because of the word \"engagement\" in YouTube's ranking sentence. A video that ranks and then loses everyone at 0:40 is a ranking that expires. What actually holds attention is covered in [improving YouTube audience retention](/blog/improve-youtube-audience-retention-watch-time).\n\n### Step 5: Write the title and description once, from the script\n\nTitle: the researched phrase, in language a human would use, with the specific promise the video keeps. Not the phrase repeated twice.\n\nDescription: the first two lines carry the phrase and the promise, because that is all most viewers see. Below that, put the timestamps your script already produced. Chapters are useful to viewers and give the description real, structured text about the video.\n\n### Step 6: Caption it, so the third input is legible\n\n\"Video content\" is one of the three ranking inputs, and a caption track is the most direct machine readable version of it that exists.\n\nGenerate the subtitles, correct the names, brands and numbers in the editor, and upload the SRT. YouTube's [captions documentation](https://support.google.com/youtube/answer/2734796) notes that subtitles let you reach a larger audience including viewers who speak another language. If you are unsure which file to hand it, see [SRT vs VTT explained](/blog/srt-vs-vtt-subtitle-formats-explained-2026).\n\nAutomatic captions are not a substitute here. They are reliably wrong on exactly the words your niche is built from, which is covered in [why auto caption errors are expensive](/blog/youtube-auto-captions-accuracy-how-to-fix-caption-errors-2026).\n\n## The tag box, and why it still exists\n\nFill it in with three obvious terms and close it.\n\nTags are not nothing. YouTube says they help correct for misspellings, which genuinely matters if your channel name or your niche has a commonly mistyped word in it. That is the whole of their job. Ten minutes of tag optimisation is ten minutes not spent on the opening thirty seconds, and only one of those two things is in the ranking sentence.\n\nThis is the single most common way a **vidiq youtube seo workflow** goes wrong: the tool surfaces a tag interface, an interface implies importance, and the creator optimises the field the platform explicitly deprioritised.\n\n## Where the two tools overlap, and which to use\n\nvidIQ writes scripts and generates thumbnails, so the overlap is real. Being fair about it:\n\n| | vidIQ | Creator AI |\n|---|---|---|\n| Keyword volume and competition | Yes | No |\n| Competitor views per hour on YouTube | Yes, via the extension | No |\n| Ideas from your channel history | Yes, Daily Ideas | Yes, with opportunity scores |\n| Script writing | Yes, 1 credit per script minute | Yes, trained on your own videos |\n| Story structure with a retention score | No | Yes |\n| Thumbnails | Yes, 22 credits each | Yes, up to 5 variants per run |\n| Subtitle file you can correct and export | No | Yes |\n| Dubbing in your own voice | No | Yes, 29 languages |\n\nUse vidIQ for the two rows only it has. Use the script and structure rows where they are the product rather than a credit line item. If you want that comparison drawn properly rather than as a table, we wrote [Creator AI vs vidIQ](/blog/creator-ai-vs-vidiq-for-youtube-creators-2026), and if you are questioning the subscription entirely, [the vidIQ alternatives roundup](/blog/best-vidiq-alternatives-for-youtube-creators-2026).\n\n## What neither tool can do for you\n\nNeither one makes the video good.\n\nvidIQ can prove a thousand people a month want this topic. Creator AI can write it in your voice and structure it so it holds. Between those two facts sits a person who has to say it convincingly on camera, and no part of this **vidiq youtube seo workflow** removes that.\n\nWhat it does remove is the illusion that the ranking problem lives in the metadata panel. It lives in the first thirty seconds. If you want the version of this argument aimed at channels under a thousand subscribers, it is in [what the YouTube algorithm actually rewards](/blog/youtube-algorithm-for-small-channels-what-it-actually-rewards-2026).\n\nYou can test the handoff without an account. The [free YouTube script generator](/tools/youtube-script-generator) turns one researched phrase into a complete script in about a minute. Run it on the last keyword vidIQ gave you and compare it to what you would have written in the tag box.\n\n## Keep Reading\n\n- [Creator AI vs vidIQ for YouTube Creators](/blog/creator-ai-vs-vidiq-for-youtube-creators-2026)\n- [The Best vidIQ Alternatives for YouTube Creators](/blog/best-vidiq-alternatives-for-youtube-creators-2026)\n- [What the YouTube Algorithm Rewards for Small Channels](/blog/youtube-algorithm-for-small-channels-what-it-actually-rewards-2026)\n- [Creator AI + ChatGPT: A Two Tool Workflow for Video Ideas](/blog/creator-ai-plus-chatgpt-youtube-workflow-for-video-ideas)\n- Research it once, then write it properly. [Start free](/signup) or [see plans](/pricing).","category":"Workflows","author_name":"Afrin Nahar","read_time":"10 min read","featured":false,"tags":["Workflow","vidIQ","YouTube SEO","Keyword Research"],"keywords":["how to use vidiq with an ai script writer","vidiq keyword research to script handoff","do youtube tags matter 2026","vidiq ai credits cost per feature","youtube seo workflow for small channels"],"faqs":[{"question":"Do YouTube tags still matter in 2026?","answer":"Barely. YouTube's own search and discovery documentation calls tags 'Not important' and says they mainly correct for common spelling mistakes. Add three obvious terms and move on. The ranking inputs the same page names are the title, the description and the video content itself."},{"question":"What should I actually take out of vidIQ?","answer":"Three things: the phrase people search, the competition estimate, and two or three related phrases to cover inside the video. Leave the SEO score, the tag suggestions and the description template. Those optimise fields YouTube has told you it deprioritises."},{"question":"How do vidIQ AI credits work?","answer":"One shared monthly pool across every AI tool, 150 credits on Free and up to 10,000 on Max depending on connected channels. AI Coach is 10 credits a message, a thumbnail is 22 credits, and script writing is 1 credit per minute of script. vidIQ's help centre states unused credits do not roll over."},{"question":"Is vidIQ's free plan enough to run this workflow?","answer":"For the research half, often yes. For the AI half, no. 150 credits is roughly fifteen coach messages or six thumbnails, which is a demonstration rather than a monthly workflow. Spend the free credits on research, which is the thing only vidIQ can do."},{"question":"Does adding subtitles help a video rank?","answer":"It makes the largest of YouTube's three ranking inputs, the video content, machine readable, and YouTube states captions let you reach a larger audience including viewers who speak another language. Upload a corrected file rather than relying on automatic captions, which fail on the terms your niche is built from."},{"question":"Should I cancel vidIQ if I use an AI script tool?","answer":"Not necessarily. They do not overlap where it counts. vidIQ reads live channel and competitor data, which a script tool has no access to. A script tool writes in your own voice and structures for retention, which vidIQ meters by the minute. The waste is paying vidIQ credits for script minutes."}],"videos":[],"branded_cta":{"title":"Get a script that sounds like you","description":"Creator AI studies videos you have already published, learns your tone and pacing, then writes full scripts against that profile instead of generic AI copy.","buttonLabel":"Write my script free","buttonHref":"/signup"},"seo_title":"vidIQ YouTube SEO Workflow 2026: Stop Optimizing Tags","seo_description":"A vidIQ YouTube SEO workflow built on what YouTube says ranks: title, description and the video itself. Six steps, real credit costs, no tag theatre.","focus_keyword":"vidiq youtube seo workflow","published_at":"2026-09-09T12:00:00.000Z"}]$blogseed$::jsonb) AS s(
  slug text,
  title text,
  excerpt text,
  content text,
  category text,
  author_name text,
  read_time text,
  featured boolean,
  tags text[],
  keywords text[],
  faqs jsonb,
  videos jsonb,
  branded_cta jsonb,
  seo_title text,
  seo_description text,
  focus_keyword text,
  published_at timestamptz
)
ON CONFLICT (slug) DO UPDATE SET
  title            = EXCLUDED.title,
  excerpt          = EXCLUDED.excerpt,
  content          = EXCLUDED.content,
  category         = EXCLUDED.category,
  author_name      = EXCLUDED.author_name,
  read_time        = EXCLUDED.read_time,
  featured         = EXCLUDED.featured,
  tags             = EXCLUDED.tags,
  keywords         = EXCLUDED.keywords,
  faqs             = EXCLUDED.faqs,
  videos           = EXCLUDED.videos,
  branded_cta      = EXCLUDED.branded_cta,
  seo_title        = EXCLUDED.seo_title,
  seo_description  = EXCLUDED.seo_description,
  focus_keyword    = EXCLUDED.focus_keyword,
  status           = EXCLUDED.status,
  published_at     = EXCLUDED.published_at,
  updated_at       = now();

DO $$
DECLARE
  n integer;
  scheduled integer;
BEGIN
  SELECT count(*) INTO n FROM public.blog_posts WHERE status = 'published';
  SELECT count(*) INTO scheduled
  FROM public.blog_posts
  WHERE status = 'published' AND published_at > now();
  RAISE NOTICE 'blog_posts: % published rows after integration workflow seed (% scheduled for a future date)', n, scheduled;
END $$;
